function createPayments() {
  const stored = new Map();
  return {
    pay(userId, key, request, charge) {
      const id = `${userId}:${key}`;
      const fingerprint = `${request.orderId}|${request.card}`;
      const entry = stored.get(id);
      if (entry && entry.fingerprint !== fingerprint) return { status: 422 };
      if (entry) return { ...entry.outcome, replayed: true };
      const outcome = charge();
      stored.set(id, { fingerprint, outcome });
      return { ...outcome, replayed: false };
    },
  };
}

let charges = 0;
const charge = () => ({ status: 201, chargeId: `ch_${++charges}` });
const payments = createPayments();
console.log(JSON.stringify(payments.pay(1, "k1", { orderId: 7, card: "tok_ok" }, charge)));
