const payments = [
  { id: 1, status: "unknown", createdAt: 0 },
  { id: 2, status: "processing", createdAt: 0 },
  { id: 3, status: "succeeded", createdAt: 0 },
  { id: 4, status: "unknown", createdAt: 950 },
];
const gatewayCharges = new Map([["pay_1", "succeeded"], ["pay_4", "succeeded"]]);

function reconcile(payments, gatewayCharges, now, cutoffMs) {
  let changed = 0;
  for (const payment of payments) {
    if (payment.status !== "processing" && payment.status !== "unknown") continue;
    if (payment.createdAt >= now - cutoffMs) continue;
    payment.status = gatewayCharges.get(`pay_${payment.id}`) ?? "declined";
    changed++;
  }
  return changed;
}

console.log(reconcile(payments, gatewayCharges, 1000, 120));
console.log(payments.map((p) => `${p.id}:${p.status}`).join(" "));

