const sent = new Set();
const delivered = [];
let calls = 0;
function sms(text, key) {
  if (++calls === 1) throw new Error("provider down");
  if (!delivered.includes(key)) delivered.push(key);
}

function handle(job) {
  const id = `${job.paymentId}:${job.kind}`;
  if (sent.has(id)) return;
  sms(`Oja Market: ${job.kind} for payment ${job.paymentId}`, `${job.kind}-${job.paymentId}`);
  sent.add(id);
}

const jobs = [{ paymentId: 1, kind: "receipt" }, { paymentId: 1, kind: "receipt" }, { paymentId: 2, kind: "declined" }];
for (const job of jobs) {
  try {
    handle(job);
  } catch {
    handle(job);
  }
}
console.log(delivered, [...sent]);

