const payments = [];

function startPayment(payments, orderId) {
  if (payments.some((p) => p.orderId === orderId && p.status !== "declined")) return { status: 409 };
  const payment = { id: payments.length + 1, orderId, status: "processing" };
  payments.push(payment);
  return payment;
}

