import { schema } from "@zudojs/schema";

const NewPayment = schema.object({
  orderId: schema.number().int().min(1),
  card: schema.string().regex(/^tok_[a-z0-9_]{2,60}$/),
});

const bodies = [
  { orderId: 7, card: "tok_ok", amountKobo: 100 },
  { orderId: 7, card: "4242424242424242" },
  { orderId: -1, card: "tok_ok" },
];
for (const body of bodies) {
  const result = NewPayment.safeParse(body);
  console.log(result.success ? result.data : result.issues.map((issue) => issue.path.join(".")));
}
